class BenefitCompensationKind(str, Enum):
    FULL_REVERSAL = "FULL_REVERSAL"
    PARTIAL_REVERSAL = "PARTIAL_REVERSAL"
    PROVIDER_CANCELLATION = "PROVIDER_CANCELLATION"
    REFUND_ADJUSTMENT = "REFUND_ADJUSTMENT"


class BenefitCompensationStatus(str, Enum):
    REQUESTED = "REQUESTED"
    SENT_TO_PROVIDER = "SENT_TO_PROVIDER"
    CONFIRMED = "CONFIRMED"
    REJECTED = "REJECTED"
    FAILED = "FAILED"


@dataclass(frozen=True)
class BenefitCompensationEvent:
    compensation_id: str
    original_application_id: str
    kind: BenefitCompensationKind
    amount: float
    currency: str
    reason: str
    source_system: str
    source_transaction_id: str
    status: BenefitCompensationStatus = BenefitCompensationStatus.REQUESTED
    provider_reference: Optional[str] = None
    evidence_reference: Optional[str] = None


def validate_benefit_compensation(event: BenefitCompensationEvent, *, original_adjustment_amount: float) -> None:
    required = {
        "compensation_id": event.compensation_id,
        "original_application_id": event.original_application_id,
        "currency": event.currency,
        "reason": event.reason,
        "source_system": event.source_system,
        "source_transaction_id": event.source_transaction_id,
    }
    for field_name, value in required.items():
        if not str(value or "").strip():
            raise ValueError(f"BenefitCompensationEvent requiere {field_name}")
    if original_adjustment_amount < 0:
        raise ValueError("original_adjustment_amount no puede ser negativo")
    if event.amount <= 0:
        raise ValueError("El monto compensatorio debe ser mayor que cero")
    if event.amount > original_adjustment_amount:
        raise ValueError("La compensacion no puede exceder el beneficio original confirmado")
    if event.kind == BenefitCompensationKind.FULL_REVERSAL and round(event.amount, 2) != round(original_adjustment_amount, 2):
        raise ValueError("FULL_REVERSAL debe compensar exactamente el beneficio original")
    if event.kind == BenefitCompensationKind.PARTIAL_REVERSAL and event.amount >= original_adjustment_amount:
        raise ValueError("PARTIAL_REVERSAL debe ser menor que el beneficio original")
    if event.status == BenefitCompensationStatus.CONFIRMED:
        if not str(event.provider_reference or "").strip():
            raise ValueError("Compensacion CONFIRMED requiere provider_reference")
        if not str(event.evidence_reference or "").strip():
            raise ValueError("Compensacion CONFIRMED requiere evidence_reference")


def remaining_effective_benefit(*, original_adjustment_amount: float, confirmed_compensations: tuple[BenefitCompensationEvent, ...]) -> float:
    if original_adjustment_amount < 0:
        raise ValueError("original_adjustment_amount no puede ser negativo")
    confirmed_total = sum(
        event.amount for event in confirmed_compensations
        if event.status == BenefitCompensationStatus.CONFIRMED
    )
    if confirmed_total > original_adjustment_amount:
        raise ValueError("Las compensaciones confirmadas exceden el beneficio original")
    return round(original_adjustment_amount - confirmed_total, 2)


def compensation_mutates_original_application() -> bool:
    return False
